CREATE TABLE preflight_runs(id BIGSERIAL PRIMARY KEY,machine_run_id BIGINT NOT NULL REFERENCES machine_runs(id),status VARCHAR(30) NOT NULL,ssh_status VARCHAR(30),authentication_status VARCHAR(30),host_verification_status VARCHAR(30),os_status VARCHAR(30),sudo_status VARCHAR(30),files_status VARCHAR(30),parameters_status VARCHAR(30),failure_reason TEXT,started_at TIMESTAMPTZ,finished_at TIMESTAMPTZ);CREATE INDEX idx_preflight_machine_run ON preflight_runs(machine_run_id);